SourceCode.Declaration:
/// <summary>
/// The outcome of a worker changing their own password.
///
/// Self-service only. Creating users, resetting other people's passwords and deactivating accounts
/// happen in D365FO, where D365FO's own security governs who may do them - none of that is exposed
/// over this service, and the handheld has no administration screen.
/// </summary>
[DataContractAttribute]
class HSMobileOpsChangePasswordResponse
{
    boolean success;
    str     errorCode;
    str     message;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// POLICY when the new password is refused, INVALID_CREDENTIALS when the current one is wrong.
/// </summary>
[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}
